param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$replacements=@(@(),@(63),@(65,66),@(0),@(65,0,66),@(0xd800,0xdc00),@(0xfffd));$byteInputs=@(@(),@(0),@(255),@(0xe2,0x82),@(0xef,0xbb,0xbf),@(65,255,66))
$actions=@(@('remaining'),@('previous'),@('next'),@('next'),@('fallback',2,-1),@('remaining'),@('next'),@('remaining'),@('previous'),@('remaining'),@('next'),@('next'),@('next'),@('next'),@('next'),@('remaining'),@('previous'),@('previous'),@('next'),@('remaining'),@('fallback',3,3),@('fallback',2,2147483647),@('fallback',-1,0),@('remaining'),@('reset'),@('fallback',-1,-1),@('remaining'),@('next'),@('previous'),@('reset'),@('fallback',0,-2147483648),@('remaining'),@('next'),@('previous'),@('next'),@('next'),@('reset'),@('fallback',1,0),@('next'),@('remaining'),@('previous'),@('next'),@('reset'),@('remaining'))
$fallbackMethod=[Text.DecoderFallbackBuffer].GetMethod('Fallback',[type[]]@([byte[]],[int]));$profiles=@()
foreach($profile in 0..7){$fallback=if($profile -eq 7){[Text.DecoderExceptionFallback]::new()}else{[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$replacements[$profile]))};$buffer=$fallback.CreateFallbackBuffer();$steps=@()
 foreach($action in $actions){$before=$buffer.Remaining;[byte[]]$bytes=$null;if($action[0] -eq 'fallback' -and $action[1] -ge 0){$bytes=[byte[]]$byteInputs[$action[1]]}
  try{switch($action[0]){'remaining'{$result=[ordered]@{ok=$true;value=$buffer.Remaining}}'previous'{$result=[ordered]@{ok=$true;value=$buffer.MovePrevious()}}'next'{$result=[ordered]@{ok=$true;value=[int]$buffer.GetNextChar()}}'reset'{$buffer.Reset();$result=[ordered]@{ok=$true;value=$null}}'fallback'{$arguments=[object[]]::new(2);$arguments[0]=$bytes;$arguments[1]=[int]$action[2];$value=$fallbackMethod.Invoke($buffer,$arguments);$result=[ordered]@{ok=$true;value=$value}}}}
  catch{$e=$_.Exception;while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};$result=[ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.DecoderFallbackException]){$result.index=$e.Index;$result.bytesUnknown=$(if($null -eq $e.BytesUnknown){$null}else{,[int[]]$e.BytesUnknown});$result.bytesReferenceSame=[object]::ReferenceEquals($bytes,$e.BytesUnknown)}}
  $steps+=[ordered]@{action=$action;remainingBefore=$before;result=$result;remainingAfter=$buffer.Remaining;bytesAfter=$(if($null -eq $bytes){$null}else{,[int[]]$bytes})}
 }
 $profiles+=[ordered]@{profile=$profile;replacementUnits=$(if($profile -lt 7){,[int[]]$replacements[$profile]}else{$null});nativeBufferType=$buffer.GetType().FullName;factoryDistinct=(-not [object]::ReferenceEquals($buffer,$fallback.CreateFallbackBuffer()));steps=$steps}
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();byteInputs=$byteInputs;profiles=$profiles;qualification='SELECTED_DECODER_FALLBACK_BUFFER_STATE_ONLY; INTERNAL_RUNTIME_TYPE_MESSAGES_CUSTOMIZATION_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned decoder buffers: eight profiles and $($actions.Count) transitions each"
